import{_ as t,o,c as s,ag as i}from"./chunks/framework.DQQHyi2x.js";const p=JSON.parse('{"title":"Config","description":"","frontmatter":{},"headers":[],"relativePath":"features/config.md","filePath":"features/config.md"}'),a={name:"features/config.md"};function r(n,e,d,l,c,u){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h1><p>The Config page lets you view, edit, and understand Claude Code settings across all configuration scopes.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Claude Code stores settings in multiple files at different scopes. The Config page provides three views:</p><ul><li><strong>Settings Editor</strong> — form-based editor for common settings</li><li><strong>Scope Resolver</strong> — shows how settings merge from different scopes</li><li><strong>Raw Viewer</strong> — displays actual configuration files</li></ul><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="settings-editor" tabindex="-1">Settings Editor <a class="header-anchor" href="#settings-editor" aria-label="Permalink to &quot;Settings Editor&quot;">​</a></h3><p>The Settings Editor tab provides form controls for common Claude Code settings:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Model</td><td>Dropdown</td><td>Claude model selection (Opus 4.6, Sonnet 4.6, Haiku 4.5, etc.)</td></tr><tr><td>Permission Mode</td><td>Dropdown</td><td>default, acceptEdits, dontAsk, plan, bypassPermissions, delegate</td></tr><tr><td>Update Channel</td><td>Dropdown</td><td>stable or latest</td></tr><tr><td>Teammate Mode</td><td>Dropdown</td><td>auto, in-process, or tmux</td></tr><tr><td>Read-only Files</td><td>Toggle</td><td>Always allow reading files without permission prompts</td></tr><tr><td>Timeouts &amp; Limits</td><td>Number inputs</td><td>Various timeout and limit settings</td></tr></tbody></table><p>The editor also includes a <strong>Permission Rules</strong> section where you can add allow/ask/deny patterns using glob syntax.</p><h3 id="scope-resolver" tabindex="-1">Scope Resolver <a class="header-anchor" href="#scope-resolver" aria-label="Permalink to &quot;Scope Resolver&quot;">​</a></h3><p>The Scope Resolver tab shows how Claude Code merges settings from four sources (highest to lowest priority):</p><ol><li><strong>Local</strong> — <code>~/.claude/settings.local.json</code> (not committed)</li><li><strong>Project</strong> — <code>.claude/settings.json</code> (project-specific)</li><li><strong>User</strong> — <code>~/.claude/settings.json</code> (user-wide)</li><li><strong>Managed</strong> — Enterprise-enforced settings (read-only)</li></ol><p>For each setting, you can see which scope provides the active value and use the &quot;Override in local&quot; button to copy a value to your local scope.</p><h3 id="raw-viewer" tabindex="-1">Raw Viewer <a class="header-anchor" href="#raw-viewer" aria-label="Permalink to &quot;Raw Viewer&quot;">​</a></h3><p>The Raw Viewer tab shows a file list on the left and file content on the right:</p><ul><li><code>~/.claude.json</code> — OAuth tokens, caches, MCP servers</li><li><code>~/.claude/settings.json</code> — User settings and permissions</li><li><code>.claude/settings.json</code> — Project settings</li><li><code>.mcp.json</code> — Project MCP servers</li><li><code>CLAUDE.md</code> — Project instructions</li><li>Command files from <code>~/.claude/commands/</code> and <code>.claude/commands/</code></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Sensitive values (tokens, secrets, passwords, API keys) are automatically masked in the merged settings view.</p></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The Config page reads and writes to the standard Claude Code configuration files. No additional Claude Deck configuration is needed.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Use the <strong>Scope Resolver</strong> to understand why a setting has a particular value — it shows the source scope.</li><li><strong>Local overrides</strong> (<code>settings.local.json</code>) take highest priority and are not committed to version control.</li><li>Permission patterns support glob syntax. The editor validates patterns and suggests fixes for deprecated syntax.</li></ul>',22)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
